  "version": "0.0.0",
  "private": true,
  "type": "module",
  "description": "poly's runtime: the polyrun host with the certificate check at load, the ledger, and the outbox intent worker (PT15, PT16, PT9.7)",
  "license": "Apache-2.0",
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "default": "./dist/src/index.js"
    },
    "./adapters": {
      "types": "./dist/src/adapters.d.ts",
      "default": "./dist/src/adapters.js"
    },
    "./model": {
      "types": "./dist/src/model.d.ts",
      "default": "./dist/src/model.js"
    }
  },
  "dependencies": {
    "@poly/core": "0.0.0",
