        result?: unknown;
        error?: string;
        permanent?: boolean;
        usage?: unknown;
    }): Promise<ReportOutcome>;
    /** S173: the run an order id belongs to, or null when no intent has that id. */
    orderRun(orderId: string): string | null;
    /** PT10: the certified workflows, as polyflow's catalogue lists them (S174). */
    workflowList(): {
