        key: string;
        note?: string;
        attached: boolean;
    }>;
    /** PT10: a run as polyflow's tools show it: its state, whether it is done, and its open work orders. */
    workflowView(instanceId: string): Promise<{
        instance: string;
        workflow: string;
        key: string;
        status: string;
        state: Record<string, unknown>;
        done: boolean;
        seq: number;
        orders: WorkOrder[];
    }>;
    /**
