     * record, which recomputes. Each problem is listed.
     */
    verifyAttribution(run: string): Promise<string[]>;
    verifyProvenance(instanceId: string): Promise<string[]>;
    getState(instanceId: string): Promise<{
        state: Record<string, unknown>;
        status: string;
        seq: number;
        machineId: string;
    }>;
    getStateAt(instanceId: string, seq: number): Promise<Record<string, unknown>>;
    getJournal(instanceId: string): Promise<JournalRow[]>;
    list(machineId: string, status?: string): Promise<import("@cognitive-fab/polygraph/polyrun/src/index.mjs").InstanceRow[]>;
    audit(instanceId?: string): Promise<{
