1	// `poly admit` (PT14, PT15, S126): check a project, and when it is CLEAN, write and sign its certificate.
2	//
3	// In M4 only a CLEAN program is admitted: accepting a finding needs a person's signature (PT12.5), which is M5's.
4	// The admission key is found by location (`env:NAME` or `file:PATH`), never committed, and a key file inside a
5	// version-controlled tree is refused. The certificate is written to a temporary name, read back against the
6	// files it describes and the signature it carries, and only then renamed into place: a certificate that does not
7	// read back is a toolchain fault, and nothing is left behind (the standing rule on artefacts the runtime reads).
8	import { readFileSync, writeFileSync, existsSync, renameSync, rmSync, mkdirSync, realpathSync, readdirSync } from 'node:fs';
9	import { basename, dirname, join, relative, resolve, sep, isAbsolute } from 'node:path';
10	import { CERTIFIED_ARTEFACTS, sha256OfBytes, certificateDigest, buildIdOf, signDigest, publicKeyOf, certificateProblems, loadProject, keyringsOf, verifyRecord, sameKeyrings, EMPTY_KEYRINGS, policySubject, advanceAnchor, } from '@poly/core';
11	import { parse } from '@poly/lang';
12	import { readEmbedded } from '@poly/embed';
13	import { checkFile, checkProject } from './pipeline.js';
14	import { STD } from './uses.js';
15	import { secretShapes } from './secrets.js';
16	import { LINT_VERSION, handlerClosure } from './handlers.js';
17	import { KeyringError, keyringChain } from './keyrings.js';
18	import { policySignaturePath } from './policy-sign.js';
19	import { readPromotions } from './promotions.js';
20	import { readProposals } from './proposals.js';
21	import { readRefits } from './refit.js';
22	const REFIT_NAME = 'REFIT_RECORD_INVALID';
23	const PROPOSAL_NAMES = { PL6520: 'PROPOSAL_RULE_UNSUPPORTED', PL6521: 'PROPOSAL_RULE_WITHOUT_EVIDENCE' };
24	const PROMOTION_NAMES = { PL6510: 'PROMOTION_NOT_IN_SOURCE', PL6511: 'PROMOTION_RECORD_INVALID', PL6512: 'SYNTHETIC_PROMOTION' };
25	export class AdmitError extends Error {
26	    constructor(message) { super(message); this.name = 'AdmitError'; }
27	}
28	/** Deliberately broken certificate writers, for the read-back's test only (test/toolchain-faults.mjs). */
29	/** Review C8 (M11): what a route's cost does not count, listed in every certificate with a route (K15, PS18.3). */
30	/** S463, PS6.4: what a machine's liveness assumes; the certificate states it with its status, and PL5409 discharges it (PS15.5). */
31	/** The statement that can reject: a require or a reject, in any branch (PS6.4, S463). */
32	function rejects(body) {
33	    return body.some((s) => s.kind === 'Require' || s.kind === 'Reject' || (s.kind === 'If' && (rejects(s.then) || rejects(s.else ?? []))) || (s.kind === 'Match' && s.arms.some((a) => rejects(a.body))) || (s.kind === 'For' && rejects(s.body)));
34	}
35	/**
36	 * S463, PS6.4: whether no completion handler of a machine can reject, by the syntax of its handlers alone: none of the
37	 * handlers of the actions that the ok, failed and exhausted outcomes of its own decisions and effects name has a require
38	 * or a reject, and the machine declares no guard (which rejects every action). Sound, not complete.
39	 */
40	export function noRejectingCompletion(machine) {
41	    if (!machine)
42	        return false;
43	    if (machine.items.some((i) => i.kind === 'Guard'))
44	        return false;
45	    const completions = new Set();
46	    for (const i of machine.items)
47	        if (i.kind === 'EffectDecl' || i.kind === 'Decision')
48	            for (const x of i.items)
49	                if (x.kind === 'EffOutcome')
50	                    completions.add(x.action);
51	    return !machine.items.some((i) => i.kind === 'Handler' && completions.has(i.action) && rejects(i.body));
52	}
53	const LIVENESS_ASSUMPTION = "machine-level liveness assumes that no completion of the program's own decisions and effects is rejected: the machine check offers a completion as an ordinary action in any state (PS4.4), and at run time a rejected completion consumes its intent";
54	const ROUTING_LIMIT = "a call's cost is its provider's usage report at the certified prices (K15): a call whose provider gave no answer reports no usage and its reservation is released, so what a provider bills for such a call is not counted; a usage report that is not whole token counts fails the call; a reservation covers the token limit at the highest price, which a call over its input tokens may exceed, recorded as an overrun";
55	export const CERTIFICATE_FAULTS = ['omit-artefact', 'stale-artefact-digest', 'digest-before-limits', 'sign-wrong-message', 'stale-handler-digest', 'omit-handler-file', 'stale-policy-digest', 'omit-policy', 'omit-package-file', 'stale-adapter-digest', 'swap-adapter-kind', 'omit-adapters', 'wrong-policy-engine', 'stale-keyring-chain', 'omit-policy-signature', 'stale-policy-signature', 'omit-vaults', 'swap-vault-store', 'rename-credential', 'swap-policy-source', 'rename-source', 'stale-source-pin', 'drop-declassify', 'swap-tier-model', 'rename-route'];
56	/** PT19, S120, S137: the most attempts a manifest entry may declare. */
57	export const MAX_ATTEMPTS = 10;
58	/** The limits every build states with its verdicts (S118, S134, S135, S142). */
59	export const M4_LIMITS = [
60	    'capabilities are bound in-process to the declared targets; what stops a handler reaching around them is the lint, a discipline, until the opt-in sandbox (PT6.5, S134, S152)',
61	    'the store is SQLite only; Postgres is not built (S135)',
62	    'installed packages are hashed, not linted: a package\'s own I/O is stopped only by the opt-in sandbox (S154)',
63	];
64	const rel = (root, p) => relative(root, p).split(sep).join('/');
65	/**
66	 * S190: where a type module's file is, as the certificate records it: relative to the project root, or `std:` and its
67	 * path under the std root. Never absolute, so an admitted project loads wherever it is copied; only the hash decides.
68	 */
69	function typeModulePath(dir, std, file, mod) {
70	    const under = (root) => { const r = relative(root, file); return r !== '' && !r.startsWith('..') && !isAbsolute(r) ? r.split(sep).join('/') : null; };
71	    const p = under(dir);
72	    if (p !== null)
73	        return p;
74	    const s = under(std);
75	    if (s !== null)
76	        return `std:${s}`;
77	    throw new AdmitError(`not admitted: module ${mod}, whose enums the build uses, is at ${file}, outside the project and outside std; the certificate records a type module by a path relative to one of them (S190)`);
78	}
79	/**
80	 * A key file inside a version-controlled tree could be committed; it is refused whatever it holds (S126). The test
81	 * walks the file's real path, so a junction or a symbolic link from outside the tree does not hide it (review A4).
82	 */
83	function insideVersionControl(file) {
84	    const lexical = resolve(file);
85	    let real = lexical;
86	    try {
87	        real = realpathSync.native(lexical);
88	    }
89	    catch {
90	        try {
91	            real = join(realpathSync.native(dirname(lexical)), basename(lexical));
92	        }
93	        catch { /* no such directory: the lexical path */ }
94	    }
95	    for (let d = dirname(real);; d = dirname(d)) {
96	        if (existsSync(join(d, '.git')))
97	            return true;
98	        if (dirname(d) === d)
99	            return false;
100	    }
101	}
102	/** Review A3, S139: the test key of `poly admit --witness`, read from a file never under version control. */
103	export function witnessKey(file) {
104	    if (insideVersionControl(file))
105	        throw new AdmitError(`the witness key is at ${resolve(file)}, inside a tree under version control; a private key is never committed (S126)`);
106	    return { id: 'witness', privateKeyPem: readFileSync(file, 'utf8') };
107	}
108	/** PT12.5, S126: a person's signing key, read from a file never under version control. */
109	export function personKey(file) {
110	    if (insideVersionControl(file))
111	        throw new AdmitError(`the person key is at ${resolve(file)}, inside a tree under version control; a private key is never committed (S126)`);
112	    return readFileSync(file, 'utf8');
113	}
114	function admissionKey(dir, named, given) {
115	    if (given)
116	        return given;
117	    if (!named)
118	        throw new AdmitError('no admission key: poly.json names none under keys.admission (S126)');
119	    const [scheme, ...rest] = named.location.split(':');
120	    const where = rest.join(':');
121	    if (scheme === 'env') {
122	        const pem = process.env[where];
123	        if (!pem)
124	            throw new AdmitError(`the admission key ${named.id} is at env:${where}, which is not set`);
125	        return { id: named.id, privateKeyPem: pem };
126	    }
127	    const file = isAbsolute(where) ? where : join(dir, where);
128	    if (insideVersionControl(file))
129	        throw new AdmitError(`the admission key ${named.id} is at ${file}, inside a tree under version control; a private key is never committed (S126)`);
130	    if (!existsSync(file))
131	        throw new AdmitError(`the admission key ${named.id} is at ${file}, which does not exist`);
132	    return { id: named.id, privateKeyPem: readFileSync(file, 'utf8') };
133	}
134	/** The certified files of each machine's build directory, by path relative to the project root. */
135	function artefactsOf(root, machines, fault, policies = []) {
136	    const out = {};
137	    // PT8: each scope's lowered policy is an artefact the runtime's gate reads.
138	    for (const p of policies)
139	        if (existsSync(join(root, p)))
140	            out[p] = sha256OfBytes(readFileSync(join(root, p)));
141	    for (const m of machines) {
142	        for (const name of CERTIFIED_ARTEFACTS) {
143	            const p = join(root, m.dir, name);
144	            if (existsSync(p))
145	                out[`${m.dir}/${name}`] = sha256OfBytes(readFileSync(p));
146	        }
147	    }
148	    if (fault === 'stale-policy-digest' && policies.length)
149	        out[policies[0]] = sha256OfBytes(policies[0]);
150	    if (fault === 'omit-policy' && policies.length)
