const SOURCES = ['conformance/m5/orders.poly', 'conformance/m5/orders.policy.poly'];
const KINDS = ['stock.reserve', 'payment.charge', 'payment.fee'];
const pct = (xs) => {
    const s = [...xs].sort((a, b) => a - b);
    const at = (q) => (s.length ? Number(s[Math.min(s.length - 1, Math.max(0, Math.ceil(q * s.length) - 1))].toFixed(3)) : 0);
    return { n: s.length, p50: at(0.5), p99: at(0.99) };
};
async function project(root, name, sources, repo) {
    const dir = join(root, name);
    mkdirSync(join(dir, 'src'), { recursive: true });
    for (const s of sources)
        copyFileSync(join(repo, s), join(dir, 'src', s.split('/').pop()));
    writeFileSync(join(dir, 'src', 'handlers.ts'), 'export async function handle(): Promise<unknown> { return {}; }\n');
    // S194, Q8: the policies are signed by a person, here a key generated for the run and held in memory, whose ring is
    // anchored in the run's own folder, read as a test anchor in this process only: the bench measures AC4's program in
    // a folder outside the repository, never the owner's project, and its certificate loads only in this process.
    const person = generateKeyPairSync('ed25519');
    const people = sources.length > 1 ? [{ name: 'bench', keyId: 'bench-person', publicKey: person.publicKey.export({ type: 'spki', format: 'pem' }).toString() }] : [];
    writeFileSync(join(dir, 'poly.json'), JSON.stringify({ poly: '1', name, modules: ['src/*.poly'], handlers: ['src/handlers.ts'], ...(people.length ? { people } : {}) }, null, 2));
    if (people.length) {
        createAnchor(join(root, `${name}.anchor`), newAnchor(name, keyringDigest({ people, agents: [] }), false));
        writeFileSync(join(root, 'anchors.json'), JSON.stringify({ anchors: { [name]: `file:${join(root, `${name}.anchor`)}` } }));
        (await import('@poly/runtime')).acceptTestAnchors();
    }
    const { privateKey, publicKey } = generateKeyPairSync('ed25519');
    const id = `bench-${name}`;
    // The run's anchor folder is the process's for the run (benchGate restores the setting): S210, load verifies the chain
    // from it as admission does.
    if (people.length)
        useTestAnchors(root);
    if (people.length)
        await signPolicy(dir, 'orders', 'bench-person', person.privateKey.export({ type: 'pkcs8', format: 'pem' }).toString(), new Date().toISOString());
    const r = await admit(dir, { key: { id, privateKeyPem: privateKey.export({ type: 'pkcs8', format: 'pem' }).toString() } });
    return { build: join(dir, '.poly', 'build'), certificate: r.certificatePath, trust: { [id]: publicKey.export({ type: 'spki', format: 'pem' }).toString() } };
}
/** One run of n orders; the gate's calls are timed by wrapping the worker's gate. */
async function series(admitted, n, timings) {
    const { load } = await import('@poly/runtime');
    const rt = await load(admitted.build, { certificate: admitted.certificate, trust: admitted.trust, worker: { batch: 4 * n + 8 } });
    try {
        const handle = rt.handlerExports('src/handlers.ts').handle;
        for (const k of KINDS)
            rt.handle(k, handle);
        const w = rt.worker;
        const inner = w.gate;
        const started = new Map();
        w.gate = {
            propose: async (p, s) => {
                const t = performance.now();
                const r = await inner.propose(p, s);
                if (timings) {
                    timings.propose.push(performance.now() - t);
                    started.set(p.idempotencyKey, t);
                }
                return r;
            },
            settle: async (o, p) => {
                const t = performance.now();
                const r = await inner.settle(o, p);
                const end = performance.now();
                if (timings) {
                    timings.settle.push(end - t);
                    const s0 = started.get(p.idempotencyKey);
                    if (s0 !== undefined)
                        timings.path.push(end - s0);
                }
                return r;
            },
        };
        const ids = Array.from({ length: n }, (_, i) => `o${i}`);
        for (const id of ids)
            await rt.create('orders.Order', { id });
        const t0 = performance.now();
        for (const id of ids)
            await rt.dispatch(id, 'Reserve', {});
        for (const id of ids)
            await rt.dispatch(id, 'Charge', {});
        for (let guard = 0; guard < 100 && (await rt.worker.tick()) > 0; guard++)
            ;
        const ms = performance.now() - t0;
        let allowed = 0;
        for (const id of ids)
            allowed += (await rt.chain(id)).filter((e) => e.kind === 'verdict' && e.body?.outcome === 'allowed').length;
        return { instances: n, effects: 2 * n, allowed, ms: Number(ms.toFixed(3)), perSecond: Number(((2 * n) / (ms / 1000)).toFixed(1)) };
    }
    finally {
        await rt.close();
    }
}
/** Runs the bench; `repo` is the checkout holding the AC4 sources. Writes the result to `out` when given. */
export async function benchGate(opts) {
    const sizes = [...(opts.sizes ?? BENCH_SIZES)];
    const { polyaxionPeer } = await import('@poly/runtime');
    const peer = polyaxionPeer();
    const root = mkdtempSync(join(tmpdir(), 'poly-bench-'));

