788	- **PT9.7 The outbox intent is a checked machine.** The interleavings of retry, gate decision, handler execution and settle are the most dangerous part of the runtime. They are specified as a poly machine, lowered like any other, and model-checked by polygraph as part of the runtime's own test suite. The runtime's outbox worker is the host of this machine.
789	
790	  ```poly
791	  module runtime
792	
793	  type Intent =
794	    | Pending
795	    | Proposed  { decision: 1..2, attempts: 0..2, rechecks: 0..2 }   // decision 2 only for an approved re-proposal
796	    | Escalated { approved: bool, attempts: 0..2, rechecks: 0..2 }
797	    | Allowed   { attempts: 0..2, rechecks: 0..2 }                   // attempts already made; rechecks of a stale allow
798	    | Running   { attempt: 1..3, rechecks: 0..2 }
799	    | Settled   { attempt: 1..3, rechecks: 0..2 }
800	    | Done | Denied | Dead
801	
802	  machine OutboxIntent {
803	    state { intent: Intent = Pending }
804	    terminal intent is Done | Denied | Dead
805	
806	    action Propose()   action GateAllow()   action GateDeny()   action GateEscalate()
807	    action Approve()   action EscalationTimeout()   action Recheck()
808	    action Start()     action HandlerOk()   action HandlerFailed()   action HandlerFailedPermanent()
809	    action SettleOk()  action SettleFailed()   action WindowLapsed()
810	
811	    on Propose {
812	      match intent {
813	        Pending => intent' = Proposed { decision: 1, attempts: 0, rechecks: 0 }
814	        Escalated { approved: true, attempts: n, rechecks: r } => intent' = Proposed { decision: 2, attempts: n, rechecks: r }
815	        _ => reject "not-proposable"
816	      }
817	    }
818	    on GateAllow    { match intent {
819	                        Proposed { attempts: n, rechecks: r } => intent' = Allowed { attempts: n, rechecks: r }
820	                        _                                     => reject "no-proposal" } }
821	    on GateDeny     { require intent is Proposed else reject "no-proposal"
822	                      intent' = Denied }
823	    on GateEscalate { match intent {
824	                        Proposed { decision: 1, attempts: n, rechecks: r } => intent' = Escalated { approved: false, attempts: n, rechecks: r }
825	                        _                                                  => reject "escalate-once" } }
826	    on Approve      { match intent {
827	                        Escalated { approved: false, attempts: n, rechecks: r } => intent' = Escalated { approved: true, attempts: n, rechecks: r }
828	                        _                                                       => reject "not-waiting" } }
829	    on EscalationTimeout { match intent {
830	                        Escalated { approved: false, attempts: _, rechecks: _ } => intent' = Denied
831	                        _                                                       => reject "not-waiting" } }
832	    on Recheck      { match intent {
833	                        Allowed { attempts: n, rechecks: r } => if r < 2 { intent' = Proposed { decision: 1, attempts: n, rechecks: r + 1 } }
834	                                                                else     { intent' = Denied }
835	                        _                                    => reject "not-allowed" } }
836	    on Start        { match intent {
837	                        Allowed { attempts: n, rechecks: r } => intent' = Running { attempt: n + 1, rechecks: r }
838	                        _                                    => reject "not-allowed" } }
839	    on HandlerOk    { match intent {
840	                        Running { attempt: n, rechecks: r } => intent' = Settled { attempt: n, rechecks: r }
841	                        _                                   => reject "not-running" } }
842	    on HandlerFailed { match intent {
843	                        Running { attempt: n, rechecks: r } => if n < 3 { intent' = Allowed { attempts: n, rechecks: r } }
844	                                                               else     { intent' = Dead }
845	                        _                                   => reject "not-running" } }
846	    on HandlerFailedPermanent { match intent {
847	                        Running => intent' = Dead
848	                        _       => reject "not-running" } }
849	    on SettleOk     { require intent is Settled else reject "not-settled"
850	                      intent' = Done }
851	    on SettleFailed { match intent {
852	                        Settled { attempt: n, rechecks: r } => if n < 3 { intent' = Allowed { attempts: n, rechecks: r } }
853	                                                               else     { intent' = Dead }
854	                        _                                   => reject "not-settled" } }
855	    on WindowLapsed { match intent {
856	                        Allowed => intent' = Dead
857	                        _       => reject "not-allowed" } }
858	
859	    step property no-reproposal-after-allow:
860	      (action != Recheck && (pre.intent is Allowed || pre.intent is Running || pre.intent is Settled))
861	        implies !(post.intent is Proposed)
862	    liveness settles: eventually intent is Done | Denied | Dead
863	      under fair { Propose, GateAllow | GateDeny | GateEscalate, EscalationTimeout, Start,
864	                   HandlerOk | HandlerFailed | HandlerFailedPermanent, SettleOk | SettleFailed }
865	  }
866	  ```
867	
868	  The state has 17 representable values, and all 17 are reachable. The v0.3 encoding as five fields had 432 representable combinations, of which 33 were reachable, plus three invariants and two step properties whose job was to rule out the rest. With the union, those properties are types:
869	
870	  - a second gate decision after execution cannot be written, because `Allowed`, `Running` and `Settled` carry no decision;
871	  - a deny after execution cannot be written, because `GateDeny` only matches `Proposed`;
872	  - `executed` is not a field, because it is `intent is Running || intent is Settled || …`.
873	
874	  One step property is kept as a regression guard, and the liveness property holds with `HandlerFailedPermanent` in the fair group of the handler's outcomes (S138), which adds three transitions and no state. **A stale allow is rechecked (S147).** `Recheck` takes `Allowed` back to `Proposed`, keeping the attempts made, when a singleton the allow read has moved on; each intent is rechecked at most twice, and a third stale allow is `Denied` with reason `stale-allow`. The bound keeps `settles` true under weak fairness, since `Recheck` is not in a fair group. The step property becomes "no re-proposal except by `Recheck`". With the rechecks the machine has 17m + 8 states at bound m: 59 at the bound 3, all reachable. An independent exploration of the machine before S138 ([`reviews/evidence/outbox_sum_check.py`](reviews/evidence/outbox_sum_check.py)) confirms 17 reachable states, no deadlock and no fair cycle outside the terminal states.
875	
876	  Three rules follow from the machine and are normative:
877	
878	  1. **One decision per execution.** Once the gate allows an intent, a retry after a timeout or a failed settle goes back to `Allowed`, not to `Proposed`. The gate is not asked again for the same idempotency key, except by `Recheck`, when the state the allow read has moved on (S147). In v0.4 this is a consequence of the type.
879	  2. **Escalation happens once and has a timeout.** An approved re-proposal can be allowed or denied, never escalated again, so an intent takes at most two gate decisions. `escalation.timeoutMs` (the polyflow platform policy field) fires `EscalationTimeout`, which denies the intent.
880	  3. **Denial is final.** A deny can only happen from `Proposed`: before any attempt ran, or after a `Recheck` found the state the allow read had moved on (S147), when the attempts already made are kept and no further one is.
881	  4. **A permanent failure is final (S138).** A handler may report a permanent error (a declined card is a result, not an infrastructure failure). `HandlerFailedPermanent` takes `Running` to `Dead` whatever attempt it is, the worker dispatches the effect's `failed` completion, and no further attempt is made. A crash is never permanent: it is `HandlerFailed`.
882	  5. **A lapsed key window ends the intent (PT33.5a, S120).** For a keyed effect, once the window has lapsed since the first attempt began, the worker takes `WindowLapsed`, which takes `Allowed` to `Dead` and starts no further attempt. It adds a transition and no state, so the machine still has 17m + 8 states at bound m, and it is not in the fair group (the worker's clock takes it, as it takes `Recheck`). The worker delivers the effect's `exhausted` completion with the observation outcome `lapsed`.
883	
884	  **The worker hosts the machine (S119).** poly-runtime runs its own effect worker, and polyrun's `tickEffects` is never started. Each intent's state is an `OutboxIntent` value in a poly-runtime table, and every worker transition is an action on the lowered `OutboxIntent` module, written in one transaction with the matching `pr_outbox` change. An action the module rejects is a runtime fault: the worker stops on that intent and reports it, and never takes the transition. A terminal transition and the completion it delivers commit in one transaction, behind the claim's fence: K1 extends to the hosted machine, so neither exists without the other, and a worker whose claim was taken over delivers nothing (review C1, C2). `Approve` and `EscalationTimeout` race, and whichever commits first wins; the other is a rejected step of the machine, journaled with its reason, and a late approval's caller gets an error saying the escalation timed out (review C3). Every park has a retry deadline. An outside dispatch to a hosted instance is refused before any step, with an audit row (review C4). A gate that throws holds only the intent it was asked about, `Proposed` with a backoff and never allowed (review C6, PT9.5). An intent keeps the bound it was created under: the runtime registers the machine of every bound the build declares and of every bound an intent in the store was created under, so a redeploy that changes a manifest's `maxAttempts` strands nothing (review C8). The machine for bound m is `runtime<m>.OutboxIntent` (`runtime.OutboxIntent` at 3), and these ids are the runtime's own: a program machine in a module named `runtime` or `runtime<m>` is `PL1208`, and `load` refuses one again, so whether a program loads never depends on the bounds or the store (S143). The only module the checker takes under those names is this model at a bound, identified by its module digest. A crash or lease expiry while `Running` is `HandlerFailed` and counts an attempt; the idempotency key (PT